import {PARTS,LABELS,COLORS,defaultCharacter,randomCharacter,characterSvg} from './characters.js';
import {doodle,roleArt} from './art.js';
import {wordmark} from './logo.js';
import {PartyAudio} from './audio.js';
import {playgroundMarkup,mountPlayground} from './playground.js';
import {castMarkup,mountGameCast} from './gameplay-cast.js';
import {ROUND_NAMES,roleState,scoreLines,revealComment,phaseGuide} from './gameplay-ui.js';
import {qrSvg} from './qr.js';
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let playground=null,gameCast=null,homeJoining=false,navigationEpoch=0,lastSignature=null,galleryIndex=0,deliveryMessage='';
let state=null,auth=null,stream=null,online=true,offset=0,network=[],busy=false,lastFrame=null,lastState=null;
let ink='#202031',brush=5,optionPage=0,scorePage=0,resultTab='answers',modal=null,avatarPart='head',editingCharacter=null,roleTarget='',clockTick='';
const redoStrokes=new Map(),drafts=new Map(),drawings=new Map(),selections=new Map(),seenRoles=new Set(),audio=new PartyAudio();
let myCharacter=defaultCharacter(Math.floor(Math.random()*8));
try{const saved=JSON.parse(localStorage.getItem('alibi-character'));if(saved)myCharacter=saved;}catch{}
const names=ROUND_NAMES;
const player=id=>state?.players.find(p=>p.id===id);
const name=id=>player(id)?.name||(String(id).startsWith('computer-')?'Computer artist':'House');
const avatar=(p,extra='',crown=false)=>`<span class="avatar ${extra}">${characterSvg(p?.character||defaultCharacter(p?.color||0),{crown})}</span>`;
const logo=()=>`<a href="/" data-home class="logo" aria-label="Alibi home">${wordmark()}</a>`;
const connection=()=>`<span class="connection ${online?'':'offline'}"><i></i><span>${online?'all good':'reconnecting…'}</span></span>`;
const roomTag=()=>`<span class="room-tag">room <b>${esc(state.code)}</b></span>`;
const smallScreen=()=>innerWidth<=680;
const frameKey=()=>`${state?.code}:${state?.round}:${state?.phase}:${state?.turn?.id||''}`;
const roasts=['That took a suspicious amount of thought.','A lie so brave it should pay rent.','Your FBI agent just closed the laptop.','Somewhere, a therapist felt a disturbance.','Confidence: 100. Evidence: absolutely fuck-all.','This friend group needs a responsible adult.','You really put that in writing. Incredible.','The bar was on the floor. You brought a shovel.'];
function roast(){const k=(state?.turn?.id||state?.code||'').split('').reduce((n,c)=>n+c.charCodeAt(0),0);return roasts[k%roasts.length];}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4300);}
async function api(path,data){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:controller.signal});const result=await response.json();if(!response.ok){const error=Error(result.error||'Something went sideways. Try again.');error.serverError=true;throw error;}return result;}finally{clearTimeout(timer);}}
function accept(result){if(!state||result.version>=state.version){state=result;offset=result.serverNow-Date.now();render(true);}}
function received(type){return type==='answer'?state?.me?.submitted:type==='question'?state?.me?.questionSubmitted:type==='drawing'?state?.me?.drawingSubmitted:type==='vote'?state?.me?.voted:type==='truth'?state?.phase==='draw':false;}
function delivery(text=''){deliveryMessage=text;const el=$('#delivery-status');if(el)el.textContent=text;}
async function action(type,extra={}){
 if(busy||!auth)return false;
 const epoch=navigationEpoch,turn=state?.turn?.id;busy=true;delivery('Sending…');
 const payload=JSON.parse(JSON.stringify({...auth,type,turnId:turn,requestId:globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`,...extra}));
 document.querySelectorAll('#submission button[type="submit"],#submit-drawing,#lock-vote,#use-power').forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');});
 try{
  let result;
  for(let attempt=0;attempt<2;attempt++){
   try{result=await api('/api/action',payload);break;}
   catch(e){if(epoch!==navigationEpoch)return false;if(e.serverError||attempt===1)throw e;delivery('Checking your submission…');}
  }
  if(epoch!==navigationEpoch)return false;accept(result);delivery(['reveal','finished'].includes(state?.phase)?'':'Received. You’re all set.');return true;
 }catch(e){if(epoch===navigationEpoch){if(received(type)&&state?.turn?.id===turn){delivery(['reveal','finished'].includes(state?.phase)?'':'Received. You’re all set.');return true;}const msg=e.serverError?e.message:'Connection interrupted. Your draft is saved. Try again.';delivery(msg);toast(msg);}return false;}
 finally{if(epoch===navigationEpoch){busy=false;document.querySelectorAll('[aria-busy="true"]').forEach(b=>{b.disabled=false;b.removeAttribute('aria-busy');});}}
}
function draftStorageKey(){return auth?`alibi-draft:${auth.room}:${auth.token}`:null;}
function persistDrafts(){try{const key=draftStorageKey();if(!key)return;sessionStorage.setItem(key,JSON.stringify({texts:[...drafts].slice(-12),drawing:state?.turn?.id&&drawings.has(state.turn.id)?[state.turn.id,drawings.get(state.turn.id)]:null}));}catch{}}
function restoreDrafts(){try{const saved=JSON.parse(sessionStorage.getItem(draftStorageKey())||'null');for(const [key,text] of saved?.texts||[])if(typeof text==='string')drafts.set(key,text);if(saved?.drawing&&Array.isArray(saved.drawing[1]))drawings.set(...saved.drawing);}catch{}}
function resetView(){
 persistDrafts();navigationEpoch++;gameCast?.destroy();gameCast=null;lastSignature=null;deliveryMessage='';
 // Keep unfinished answers and room credentials available for Forward/reconnect.
 const key=app.dataset.draftKey;
 if(key)document.querySelectorAll('[data-draft]').forEach(el=>drafts.set(`${key}:${el.dataset.draft}`,el.value));
 stream?.close();stream=null;closeModal();playground?.destroy();playground=null;
 initCanvas.observer?.disconnect();clearTimeout(transition.timer);clearTimeout(celebrate.timer);clearTimeout(toast.timer);
 $('#transition').className='transition';$('#transition').innerHTML='';$('#celebration').innerHTML='';$('#toast').classList.remove('visible');
 state=null;auth=null;lastFrame=null;lastState=null;busy=false;online=true;clockTick='';
 delete app.dataset.draftKey;
}
function navigate(path){
 if(location.pathname+location.search!==path)history.pushState({alibiFromMenu:location.pathname==='/'&&!homeJoining},'',path);
 route();
}
function backToMenu(){
 if(history.state?.alibiFromMenu)history.back();else navigate('/');
}
function route(){
 resetView();
 const params=new URLSearchParams(location.search),room=params.get('room')?.toUpperCase(),host=location.pathname==='/host';
 let saved=null;
 try{saved=room&&!params.has('fresh')?JSON.parse(sessionStorage.getItem(`${host?'host':'seat'}-${room}`)):null;}catch{}
 if(saved?.room===room&&typeof saved?.token==='string'){
  auth=saved;restoreDrafts();audio.setHost(host);document.body.dataset.view=host?'host':'phone';
  app.innerHTML=`<main class="error-page">${logo()}<h1>Opening your room…</h1><p>Getting everyone on the same page.</p><a href="/" data-home class="text-button back-menu">Back to menu</a></main>`;connect();
 }else landing(location.pathname==='/join'||!!room);
}
function saveAuth(result,host){
 const session={room:result.room,token:result.token};
 sessionStorage.setItem(`${host?'host':'seat'}-${session.room}`,JSON.stringify(session));
 navigate(`${host?'/host':'/join'}?room=${session.room}`);
}
function connect(){
 stream?.close();
 const epoch=navigationEpoch,session={...auth},connection=new EventSource(`/api/events?room=${encodeURIComponent(session.room)}&token=${encodeURIComponent(session.token)}`);
 stream=connection;
 const current=()=>epoch===navigationEpoch&&stream===connection;
 connection.onmessage=e=>{if(!current())return;online=true;accept(JSON.parse(e.data));};
 connection.onopen=()=>{if(!current())return;online=true;updateConnection();};
 connection.onerror=async()=>{
  if(!current())return;online=false;updateConnection();
  try{
   const r=await fetch(`/api/state?room=${encodeURIComponent(session.room)}&token=${encodeURIComponent(session.token)}`);
   if(r.status===400){const result=await r.json();if(!current())return;resetView();audio.setMenu();app.innerHTML=`<main class="error-page">${logo()}<h1>That room is no longer here.</h1><p>${esc(result.error)}</p><a href="/" data-home class="btn red">Back to menu</a></main>`;}
  }catch{}
 };
}
function updateConnection(){document.querySelectorAll('.connection').forEach(el=>{el.classList.toggle('offline',!online);el.querySelector('span').textContent=online?'connected':'reconnecting…';});document.querySelectorAll('.connection-notice').forEach(el=>el.hidden=online);}

const homeDraft={room:null,name:''};
function landing(joining=!!new URLSearchParams(location.search).get('room')){
 playground?.destroy();playground=null;homeJoining=joining;
 if(joining)audio.setHost(false);else audio.setMenu();
 document.body.dataset.view='home';
 const code=homeDraft.room??new URLSearchParams(location.search).get('room')??'';
 app.innerHTML=`<main class="home desk home-clear home-playground ${joining?'is-joining':'is-choosing'}"><div class="binding" aria-hidden="true"></div>
 ${joining?'':`<header class="home-top">${audioButton()}</header>`}
 <section class="home-main"><div class="home-story">
 <h1 class="home-logo">${wordmark()}</h1>
 <h2 class="home-premise">Your friends are the trivia.</h2>
 <p class="home-explainer">Make up lies. Find the truth.<br>Finish with terrible drawings.</p>
 <p class="play-facts">2–8 players</p>
 </div><div class="join-area"><span class="join-arrow">your alibi starts here ${doodle('arrow')}</span>
 <section class="join-sheet"><div class="tape" aria-hidden="true"></div>
 ${joining?`<button class="text-button back-home" id="back-home">← back</button><h2>get in here.</h2><p class="join-instruction">Use the code on your friend's screen.</p>
 <form id="join-form"><label for="room">room code</label><input id="room" name="room" class="code-input" value="${esc(code)}" placeholder="ABCD" maxlength="4" minlength="4" required autocomplete="off" autocapitalize="characters" pattern="[A-Za-z]{4}">
 <label for="name">your alias</label><input id="name" name="name" value="${esc(homeDraft.name)}" placeholder="something your mum regrets" maxlength="20" required autocomplete="nickname">
 <button class="character-pick" type="button" id="pick-character">${avatar({character:myCharacter})}<span>pick your little freak<small>hats. bad hair. worse outfits.</small></span><span class="edit-arrow">↗</span></button>
 <button class="btn red full" type="submit">Join game</button></form>`:
 `<h2>get in here.</h2><button class="btn red full" id="choose-join">Join a game</button><p class="choice-hint">Already have a room code?</p>
 <button class="btn yellow full" id="create-room">Host a game</button><p class="choice-hint">On a laptop or TV.</p>
 <div class="preview-divider" aria-hidden="true"></div><button class="preview-button" id="watch-preview"><span class="preview-thumbnail"><img src="/media/preview-poster.webp" alt="" width="1280" height="720"><span class="play-icon" aria-hidden="true">▶</span></span><span><b>See it in action</b></span></button>`}
 </section>${doodle('star','sticker home-star')}${doodle('pencil','sticker home-pencil')}</div></section>
 ${playgroundMarkup()}
 <footer class="home-footer"><span class="footer-note">made for people who know too much.</span><nav aria-label="About Alibi"><button class="text-button" id="how-to">how to play</button><button class="text-button" id="about-project">about the project</button></nav></footer><span class="page-number">006 / alibi</span></main>`;
 if(joining){
  $('#room').oninput=e=>homeDraft.room=e.target.value;
  $('#name').oninput=e=>homeDraft.name=e.target.value;
  $('#back-home').onclick=backToMenu;
  $('#pick-character').onclick=()=>openCharacter();
  $('#join-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter,epoch=navigationEpoch;button.disabled=true;try{const values=new FormData(e.target),result=await api('/api/join',{room:values.get('room').toUpperCase(),name:values.get('name'),character:myCharacter});if(epoch===navigationEpoch)saveAuth(result,false);}catch(err){if(epoch===navigationEpoch){toast(err.message);button.disabled=false;}}};
 }else{
  $('#choose-join').onclick=()=>{navigate('/join');$('#room').focus();};
  $('#watch-preview').onclick=()=>{modal='preview';renderModal();};
  $('#create-room').onclick=async e=>{const button=e.currentTarget,epoch=navigationEpoch;button.disabled=true;button.textContent='getting the gang together…';audio.setHost(true);audio.enable({automatic:true});try{const result=await api('/api/rooms',{});if(epoch===navigationEpoch)saveAuth(result,true);}catch(err){if(epoch===navigationEpoch){toast(err.message);audio.setMenu();button.disabled=false;button.textContent='Host a game';}}};
 }
 if($('#sound-settings'))$('#sound-settings').onclick=()=>{modal='audio';renderModal();};
 $('#how-to').onclick=()=>{modal='rules';renderModal();};
 $('#about-project').onclick=()=>{modal='about';renderModal();};
 playground=mountPlayground(app.querySelector('.home'),{quiet:joining});
}
function audioButton(){return `<button class="sound-button" id="sound-settings" aria-label="Music settings">${audio.loading?'♫ loading':audio.enabled?'♫ on':'♫ music'}</button>`;}
function updateAudioButtons(){document.querySelectorAll('#sound-settings').forEach(el=>{el.textContent=audio.loading?'♫ loading':audio.enabled?'♫ on':'♫ music';});document.querySelectorAll('#toggle-audio').forEach(el=>{el.disabled=audio.loading;el.textContent=audio.loading?'loading music…':audio.enabled?'mute the music':'play music ♫';});document.querySelectorAll('#audio-status').forEach(el=>el.textContent=audio.error);}
audio.onChange=updateAudioButtons;
function header(){return `<header class="topbar">${state.host?`<div class="host-brand">${logo()}<a href="/" data-home class="text-button back-menu">Back to menu</a></div>`:logo()}${state.host?`<span class="top-scribble">${state.phase==='lobby'?'roll call, you weirdos.':names[state.round]||'nice work, liars.'}</span>`:`<span class="identity">${avatar(player(state.me.id))}<b>${esc(name(state.me.id))}</b></span>`}<div class="row">${state.host?audioButton():''}${roomTag()}</div></header>`;}
function nextStepLabel(){return state.round===3?'Final results':state.turnIndex+1===state.turnCount?'Next round':'Next question';}
function revealStatus(seconds=Math.max(0,Math.ceil(((state.paused?state.remaining:state.deadline-state.serverNow)||0)/1000))){return state.paused?'Paused by host':`${nextStepLabel()} in ${seconds}s`;}
function clockLabel(){return state.paused?'paused':state.phase==='reveal'?'next in':'hurry up.';}
function scorePageSize(){if(state.host)return 8;const height=window.visualViewport?.height||innerHeight;const count=height<600?1:height<740?2:height<860?3:4;return state.phase==='reveal'&&(state.turn?.prompt?.length>120||(state.turn?.truth?.length||0)>80)?Math.max(1,count-1):count;}
function stagebar(){const timed=state.phaseDuration&&(state.deadline||state.paused);return `<div class="stagebar"><div class="round-progress">${[1,2,3].map(n=>`<span class="${state.round===n?'current':''}" aria-label="Round ${n}">${n}</span>`).join('')}<b>${state.phase==='finished'?'the damage':state.phase==='reveal'?'busted.':state.phase==='questions'?'make it personal.':`round ${state.round}`}</b></div>${timed?`<div class="countdown ${state.host?'tv-countdown':''} ${state.paused?'is-paused':''}"><span class="clock-note">${clockLabel()}</span><div class="timer" role="timer">0:00</div><div class="countdown-track"><div class="countdown-fill"></div></div></div>`:`<span class="stage-note">${state.phase==='finished'?'everybody has receipts.':`${state.turnIndex+1} / ${state.turnCount}`}</span>`}</div>`;}
function promptBlock(){const text=state.me?.personalPrompt||state.turn.prompt;return `<section class="prompt-stage ${text.length>115?'long-prompt':''}"><p class="eyebrow">${state.round===3?'the drawing finale':`about ${esc(name(state.turn.subject))}`}</p><h2>${esc(text)}</h2></section>`;}

function statuses(){const ids=state.phase==='truth'?[state.turn.subject]:state.phase==='draw'?state.turn.artists:state.phase==='vote'?state.turn.voters:state.phase==='write'?state.turn.writers:state.players.map(p=>p.id),people=state.players.filter(p=>ids?.includes(p.id));return `<div class="submission-status"><span class="status-total">${people.filter(p=>p.ready).length} / ${people.length} ready</span><div class="status-grid">${people.map(p=>`<div class="status-chip ${p.ready?'done':''}" title="${esc(p.name)}: ${p.ready?'ready':p.connected===false?'reconnecting':'thinking'}">${avatar(p)}<span>${esc(p.name)}</span><b>${p.ready?'✓':p.connected===false?'…':'✎'}</b></div>`).join('')}</div><small>Next up as soon as everyone’s ready.</small></div>`;}

function playerWall(){return `<div class="player-wall">${state.players.map((p,i)=>`<div class="player-polaroid" style="--tilt:${[-5,4,-2,6,2,-4,3,-3][i]}deg;--order:${i}"><i class="tape"></i>${avatar(p)}<strong>${esc(p.name)}</strong>${state.host?`<button class="remove-player" data-kick="${p.id}" aria-label="Remove ${esc(p.name)}">×</button>`:''}</div>`).join('')}${Array.from({length:Math.max(0,4-state.players.length)},()=>`<div class="empty-polaroid">${doodle('smile')}<span>could be you.</span></div>`).join('')}</div>`;}
function hostLobby(){const origin=network[0]||location.origin,url=`${origin}/join?room=${state.code}`;return `<div class="lobby-grid"><section class="lobby-invite paper-note"><i class="tape"></i><p class="eyebrow">your game night starts here</p><h1>Come on in.</h1><div class="bigcode" aria-label="Room code ${state.code}">${state.code}</div><div class="join-qr">${qrSvg(url)||''}</div><p>Scan to join, or open</p><a class="network-url" href="${esc(url)}">${esc(origin)}</a><div class="lobby-links"><button class="text-button" id="copy-link">Copy invite</button><a class="text-button" href="/join?room=${state.code}&fresh=1" target="_blank" rel="noopener">Open player tab</a></div></section><section class="lobby-cast"><div class="cast-heading"><h2>The usual suspects.</h2><span>${state.players.length}/8 here</span></div>${castMarkup(state.players,{couch:true})}<div class="cast-roster">${state.players.map(p=>`<span>${esc(p.name)}<button class="remove-player" data-kick="${p.id}" aria-label="Remove ${esc(p.name)}">×</button></span>`).join('')}</div>${state.players.length?'':'<p class="empty-couch">Seats available. Good judgment optional.</p>'}<div class="lobby-start"><span>${state.players.length<2?'Bring at least one friend.':'Everyone here? Let’s see what they’re hiding.'}</span><button class="btn red" data-action="start" ${state.players.length<2?'disabled':''}>Start game</button></div></section></div>`;}

function drawingSvg(strokes=[]){return `<svg class="drawing-art" viewBox="0 0 600 450" role="img" aria-label="Player drawing"><rect width="600" height="450" fill="#fff"/>${strokes.map(s=>s.points.length===1?`<circle cx="${s.points[0][0]*600}" cy="${s.points[0][1]*450}" r="${s.size/2}" fill="${s.color}"/>`:`<polyline points="${s.points.map(p=>`${p[0]*600},${p[1]*450}`).join(' ')}" stroke="${s.color}" stroke-width="${s.size}" fill="none" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}</svg>`;}
function pageSize(){if(state.host)return 20;if(state.round===3)return 2;const max=Math.max(0,...state.turn.options.map(o=>(o.text||'').length));if(max>90)return 1;return innerHeight<760||max>55||state.turn.prompt.length>115?2:4;}
function pager(page,count,kind){return count>1?`<nav class="pager" aria-label="${kind==='options'?'Answer':'Score'} pages"><button data-page="${kind}" data-step="-1" aria-label="Previous page" ${page===0?'disabled':''}>←</button><span>${page+1} / ${count}</span><button data-page="${kind}" data-step="1" aria-label="Next page" ${page===count-1?'disabled':''}>→</button></nav>`:'';}
function options(reveal=false,interactive=false){const t=state.turn,chosen=selections.get(t.id)||[],size=pageSize(),pages=Math.ceil(t.options.length/size);optionPage=Math.max(0,Math.min(optionPage,pages-1));const start=optionPage*size;
return `<div class="answer-board"><div class="options ${state.round===3?'drawings':''} count-${Math.min(size,t.options.length)}">${t.options.slice(start,start+size).map((o,j)=>{const i=start+j,eliminated=state.me?.hint?.eliminated===o.id,selected=chosen.includes(o.id);return `<article class="answer-wrap" data-answer="${o.id}" style="--tilt:${[-1.5,1.2,-.6,1.8][i%4]}deg;--order:${j}"><${interactive?'button':'div'} ${interactive?`type="button" data-option="${o.id}" aria-pressed="${selected}" ${o.owned||eliminated?'disabled':''}`:''} class="option scrap-${i%4} ${selected?'selected':''} ${reveal&&o.truth?'truth':''} ${!reveal&&o.owned?'owned':''}"><div class="option-title"><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(o.text||`Drawing ${String.fromCharCode(65+i)}`)}</span>${reveal&&o.truth?'<span class="truth-stamp">TRUE</span>':''}</div>${o.drawing?drawingSvg(o.drawing):''}${!reveal&&(o.owned||eliminated)?`<small class="option-meta">${o.owned?'Your answer · can’t vote for this':'Crossed off by your Detective power'}</small>`:''}${selected&&!reveal?'<span class="selection-check" aria-hidden="true">✓</span>':''}${reveal?`<div class="option-meta">${o.truth?`The truth${state.round===3?` · drawn by ${esc(name(t.artist))}`:''}`:`${o.owners.length?o.owners.map(pid=>esc(name(pid))).join(' + '):'House'}’s bluff`}</div><div class="voters">${o.voters.map(pid=>`<span class="voter" title="${esc(name(pid))}">${avatar(player(pid))}<span>${esc(name(pid))}</span></span>`).join('')||'<small>No votes</small>'}</div>`:''}</${interactive?'button':'div'}>${o.drawing?`<button type="button" class="enlarge-drawing" data-enlarge="${i}" aria-label="Enlarge drawing ${String.fromCharCode(65+i)}">Look closer</button>`:''}</article>`;}).join('')}</div>${pager(optionPage,pages,'options')}</div>`;}
function voteTray(){const ids=selections.get(state.turn.id)||[],labels=ids.map(id=>{const i=state.turn.options.findIndex(o=>o.id===id);return `${String.fromCharCode(65+i)}${state.round<3?`: ${state.turn.options[i]?.text}`:''}`;});return `<div class="vote-tray" role="status">${labels.length?`Selected: ${esc(labels.join(' + '))}`:state.me.power?.role==='lucky'?'Choose up to two answers.':'Choose an answer, then lock your vote.'}</div>`;}
function scoreReceipt(){if(!state.me)return '';const rows=scoreLines(state,state.me.id),total=state.turn?.deltas?.[state.me.id]||0;return `<div class="score-receipt"><b>${total>0?'+':''}${total.toLocaleString()} points</b>${rows.length?rows.map(r=>`<span>${esc(r.reason)}${r.count>1?` × ${r.count}`:''}<strong>${r.points>0?'+':''}${r.points}</strong></span>`).join(''):`<span>${state.turn?.skipped?'No points awarded this turn.':state.me.isSubject&&state.round<3?'Your friends did the guessing this turn.':'No points this turn. Fresh chance next question.'}</span>`}</div>`;}

function leaderboard(){const sorted=[...state.players].sort((a,b)=>b.score-a.score),size=scorePageSize(),pages=Math.ceil(sorted.length/size);scorePage=Math.min(scorePage,pages-1);let rank=0,last=null;return `<div class="score-sheet"><h3>the damage.</h3><div class="leaderboard">${sorted.map((p,i)=>{if(last!==p.score)rank=i+1;last=p.score;return {p,i,rank};}).slice(scorePage*size,(scorePage+1)*size).map(({p,i,rank})=>`<div class="score-row" data-score-player="${p.id}" style="--order:${i}"><span class="rank">${rank}</span>${avatar(p)}<span class="name" title="${esc(p.name)}">${esc(p.name)}${state.phase==='finished'&&p.role?`<small class="final-role">${esc(p.role.name)}</small>`:''}</span><span class="score-numbers">${state.turn?.deltas?.[p.id]?`<span class="delta">${state.turn.deltas[p.id]>0?'+':''}${state.turn.deltas[p.id]}</span>`:''}<b class="score" data-score="${p.score}">${p.score.toLocaleString()}</b></span></div>`).join('')}</div>${pager(scorePage,pages,'scores')}</div>`;}
function results(){return `${promptBlock()}${state.turn.skipped?`<div class="notice">${esc(state.turn.skipReason)}</div>${leaderboard()}`:`<div class="reveal-summary">The truth was <strong>${esc(state.turn.truth)}</strong></div>${!state.host?`<div class="result-tabs" role="group" aria-label="Turn results"><button aria-pressed="${resultTab==='answers'}" data-result-tab="answers" class="${resultTab==='answers'?'active':''}">Answers</button><button aria-pressed="${resultTab==='scores'}" data-result-tab="scores" class="${resultTab==='scores'?'active':''}">Scores</button></div>`:''}<div class="reveal-layout ${!state.host&&resultTab==='scores'?'phone-score-results':''}">${state.host||resultTab==='answers'?options(true):''}${state.host||resultTab==='scores'?`${scoreReceipt()}${leaderboard()}`:''}</div>`}`;}

function finished(){const max=Math.max(...state.players.map(p=>p.score)),winners=state.players.filter(p=>p.score===max),winnerIds=new Set(winners.map(p=>p.id));const cast=state.players.map(p=>winnerIds.has(p.id)?{...p,character:{...p.character,hat:'crown'}}:p);return `<section class="winner-stage"><p class="eyebrow">${winners.length>1?'Shared custody of the crown.':'A very questionable champion.'}</p><h1>${winners.map(p=>esc(p.name)).join(' + ')}</h1><p>${max.toLocaleString()} points. Don’t let it go to your head.</p>${castMarkup(cast,{couch:true})}</section>${state.host?`<div class="match-awards">${(state.awards||[]).map(a=>`<div><b>${esc(a.title)}</b><span>${a.players.map(name).map(esc).join(' + ')}</span><small>${a.value}${a.title==='Biggest comeback'?' points recovered':''}</small></div>`).join('')}</div>`:''}${leaderboard()}${state.host?'<div class="finish-actions"><button class="btn red again" data-action="restart">Play again</button><a href="/" data-home class="text-button">Back to menu</a></div>':'<p class="progress-note">Same characters. Another round? Ask the host.</p>'}`;}

function waiting(title,description,kind='smile'){const me=state.me&&player(state.me.id);return `<div class="waiting">${me?castMarkup([me],{solo:true}):doodle(kind,'waiting-doodle')}<h3>${title}</h3><p>${description}</p><small class="roast">${roast()}</small></div>`;}

function hostView(){let body='';if(state.phase==='lobby')body=hostLobby();else if(state.phase==='finished')body=finished();else if(state.phase==='reveal')body=results();else if(state.phase==='questions')body=`<section class="prompt-stage"><p class="eyebrow">round two · your questions</p><h2>Make it personal.</h2></section><p class="stage-instruction">${phaseGuide(state)}</p>${statuses()}`;else{body=promptBlock();if(state.phase==='mixing')body+=`<div class="mixing-note">Shuffling the papers…<small>Your full voting timer starts when the choices are ready.</small></div>`;else{body+=`<p class="stage-instruction">${esc(phaseGuide(state))}</p>`;if(state.phase==='vote')body+=options();body+=statuses();if(state.phase==='draw')body+='<p class="drawing-rule">Pictures only. No words or initials.</p>';}}
const cast=!['lobby','finished'].includes(state.phase)?castMarkup(state.players):'';
return `<main class="shell host desk phase-${state.phase}">${header()}${state.phase!=='lobby'?stagebar():''}<div class="stage-content">${body}</div>${cast}${connectionNotice()}<div id="pause-layer">${pauseLayer()}</div><footer class="host-controls"><span>${state.phase==='lobby'?'One shared screen. Everyone joins on their own device.':state.phase==='reveal'?`${esc(revealComment(state))}<small class="auto-next-note" data-next-status>${revealStatus()}</small>`:state.phase==='finished'?'Same friends. New accusations.':'Answers on your phones. Drama up here.'}</span>${!['lobby','finished'].includes(state.phase)?`<div class="row"><button class="text-button" data-action="pause">${state.paused?'Resume':'Pause'}</button>${state.phase==='reveal'?`<button class="btn red small" data-action="next">${nextStepLabel()} now</button>`:'<button class="text-button" id="end-timer">End timer</button>'}</div>`:connection()}</footer></main>`;}
function pauseLayer(){return state.paused?`<div class="pause-overlay"><span>Pencils down.</span><p>${state.host?'Resume whenever everyone’s ready.':'The host paused the game.'}</p>${state.host?'<button class="btn yellow" data-action="pause">Resume game</button>':''}</div>`:'';}
function connectionNotice(){return `<div class="connection-notice" role="status" ${online?'hidden':''}>Reconnecting. Your draft is saved on this device.</div>`;}

function roleTrigger(){const role=state.me?.role,r=roleState(state);return role&&state.round<3?`<button class="role-trigger ${state.me.used?'used':''} ${r.available?'power-ready':''}" id="open-role">${doodle({detective:'magnify',gambler:'dice',forger:'pencil',accomplice:'heart',bounty:'target',reader:'eye',showboat:'star',lucky:'clover'}[role.id])}<span>${esc(role.name)}<small>${esc(r.label)}${state.round===2&&!state.me.used?' · last round to use it':''}</small></span></button>`:connection();}

function textForm(type,label,placeholder,max=140){return `<form id="submission" data-type="${type}"><label for="answer">${label}</label><textarea id="answer" name="text" data-draft="text" required maxlength="${max}" placeholder="${esc(placeholder)}" rows="2"></textarea><div class="input-meta"><span>Short answers sell better.</span><span id="character-count">0 / ${max}</span></div>${type==='question'?`<button type="button" class="text-button question-starter" id="question-starter">Need a question starter?</button>`:''}${type==='answer'&&state.me.isSubject&&state.players.length===2?'<label for="lie">Now add one believable lie</label><input id="lie" name="lie" data-draft="lie" required maxlength="140" placeholder="Something they might actually believe.">':''}${type==='answer'&&state.me.power?.role==='forger'?'<label for="second">Your extra lie · Forger</label><input id="second" name="second" data-draft="second" required maxlength="140" placeholder="A second chance to cause problems.">':''}<button class="btn red full" type="submit">${type==='question'?'Submit question':type==='truth'||state.me.isSubject?'Submit truth':'Submit lie'}</button></form>`;}

function phoneDraw(){const me=state.me;if(!me.canDraw)return waiting('Your answer is in.','Watch the drawings. Keep a straight face.','mug');if(me.drawingSubmitted)return waiting('Drawing received.','The Louvre will be in touch. Probably not.','pencil');return `<div class="drawing-assignment ${me.informed?'informed':''}">${me.informed?`<small>Only you see the answer. Draw this:</small><strong>${esc(me.truth)}</strong>`:`Draw your best guess: what did ${esc(name(state.turn.subject))} answer?`}</div><div class="canvas-wrap"><canvas id="drawing" width="600" height="450" aria-label="Draw with your finger or mouse"></canvas></div><div class="draw-tools"><div class="swatches">${['#202031','#7655ed','#ee6654','#49a797','#ffffff'].map((c,i)=>`<button type="button" class="swatch ${c===ink?'active':''}" style="--swatch:${c}" data-ink="${c}" aria-label="${['Ink','Purple','Red','Green','Eraser'][i]}" aria-pressed="${c===ink}">${i===4?'⌫':''}</button>`).join('')}</div><select id="brush" aria-label="Pen size"><option value="3">Fine</option><option value="5">Pen</option><option value="12">Marker</option></select><button class="text-button" id="undo" aria-label="Undo last stroke">Undo</button><button class="text-button" id="redo" aria-label="Redo stroke">Redo</button><button class="text-button" id="clear">Clear</button></div><div class="drawing-submit"><small>No words or initials.</small><button class="btn red" id="submit-drawing">Submit drawing</button></div>`;}

function phoneView(){const me=state.me;let body='';if(state.phase==='lobby')body=`<section class="phone-lobby"><p class="eyebrow">you're in, ${esc(name(me.id))}.</p>${castMarkup([player(me.id)],{couch:true,solo:true})}<h1>You’re in.</h1><button class="btn yellow" id="edit-character">Edit character</button><div class="mini-cast">${state.players.map(p=>`<span title="${esc(p.name)}">${avatar(p)}<small>${esc(p.name)}</small></span>`).join('')}</div><p>The host will start the game.</p></section>`;else if(state.phase==='finished')body=finished();else if(state.phase==='reveal')body=results();else if(state.phase==='questions')body=`<section class="prompt-stage"><p class="eyebrow">your turn to cause problems</p><h2>ask ${esc(name(me.questionTarget))} something weird.</h2><p>One question. Use their name. Make them confess.</p></section>${me.questionSubmitted?waiting('Question received.','Your friend has some explaining to do.','eye'):textForm('question','your question',`What would ${name(me.questionTarget)} get banned from a petting zoo for?`,180)}`;else{body=promptBlock();if(state.phase==='mixing')body+=waiting('Shuffling the papers…','Your voting timer starts when the choices are ready.','worm');if(state.phase==='write')body+=state.players.length===2&&!me.isSubject?waiting('put your bullshit detector on.',`${esc(name(state.turn.subject))} is writing a truth and a lie. You guess next.`,'eye'):me.submitted?waiting('Answer received.','Try looking less pleased with yourself.','thumb'):`<p class="assignment">${me.isSubject?'This is about you. Answer honestly.':'Write a believable answer about your friend.'}</p>${textForm('answer',me.isSubject?'Your honest answer':'Your lie','Keep it short. Make it believable.')}${me.isSubject?'<button class="text-button skip" data-action="skip">Different question</button>':''}`;
if(state.phase==='truth')body+=me.isSubject?`${me.drawingIssue?`<p class="notice">${esc(me.drawingIssue)}</p>`:''}<p class="assignment">${state.players.length===2?'Answer honestly. The computer will draw it; your opponent guesses.':'Answer honestly. One other player will get your answer to draw.'}</p>${textForm('truth','your answer','A short, drawable answer',80)}<button class="text-button skip" data-action="skip">Different question</button>`:waiting(`${esc(name(state.turn.subject))} is confessing.`,'You’ll get your drawing assignment next.','eye');if(state.phase==='draw')body+=phoneDraw();if(state.phase==='vote'){if(!me.canVote)body+=waiting('You know the answer.',state.round===3?'Keep the answer secret. You earn 500 for each correct guess.':'Let them guess. Try not to look so smug.','eye');else if(me.voted)body+=waiting('Vote received.','Look up. The reveal is coming.','thumb');else body+=`<p class="assignment">${state.round===3?'Find the artist who knew the answer.':'Find the truth.'} ${me.power?.role==='lucky'?'Pick up to two.':''}</p>${options(false,true)}${voteTray()}<button class="btn red full" id="lock-vote" ${(selections.get(state.turn.id)||[]).length?'':'disabled'}>Lock vote</button>`;}}
return `<main class="shell phone desk phase-${state.phase}">${header()}${state.phase!=='lobby'?stagebar():''}<div class="stage-content">${body}</div><footer class="phone-footer">${roleTrigger()}<span ${state.phase==='reveal'?'data-next-status':''}>${state.phase==='reveal'?revealStatus():state.phase==='lobby'?'Make yourself at home.':'keep your screen to yourself.'}</span></footer><p id="delivery-status" class="delivery-status" role="status">${esc(deliveryMessage)}</p>${connectionNotice()}<div id="pause-layer">${pauseLayer()}</div></main>`;}
function draftKey(){return `${state?.phase}:${state?.turn?.id||state?.round}:${state?.me?.id}`;}
function viewSignature(){return JSON.stringify([frameKey(),state.host?state.phase==='lobby'?state.players.map(p=>[p.id,p.name]):null:state.me,state.phase==='lobby'?state.players.map(p=>state.host?p.id:[p.id,p.character]):null]);}
function patchLive(){
 const box=$('.submission-status');if(box){const holder=document.createElement('div');holder.innerHTML=statuses();box.replaceWith(holder.firstElementChild);}
 const pause=$('#pause-layer');if(pause){pause.innerHTML=pauseLayer();pause.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));}
 document.querySelectorAll('.host-controls [data-action="pause"]').forEach(el=>el.textContent=state.paused?'Resume':'Pause');
 const trigger=$('#open-role');if(trigger){const holder=document.createElement('div');holder.innerHTML=roleTrigger();trigger.replaceWith(holder.firstElementChild);$('#open-role').onclick=()=>{modal='role';renderModal();};}
 gameCast?.update(state);updateTimer();updateConnection();audio.paused=state.paused;
}
function render(fromNetwork=false){
 if(!state)return;
 playground?.destroy();playground=null;
 const frame=frameKey(),changed=frame!==lastFrame,oldState=lastState,signature=viewSignature();
 if(fromNetwork&&!changed&&signature===lastSignature){patchLive();if(modal==='role')renderModal();if(state.host&&oldState&&state.players.filter(p=>p.ready).length>oldState.players.filter(p=>p.ready).length)audio.effect('submit');lastState=JSON.parse(JSON.stringify(state));return;}
 if(!state.host&&oldState?.phase==='write'&&state.phase==='write'&&oldState.turn?.id===state.turn?.id&&oldState.me?.submitted&&!state.me.submitted)toast('That answer is already taken. Try a different lie.');
 const scoreRects=new Map([...document.querySelectorAll('[data-score-player]')].map(el=>[el.dataset.scorePlayer,el.getBoundingClientRect()]));
 if(changed){optionPage=0;scorePage=0;resultTab='answers';deliveryMessage='';if(state.phase==='lobby')seenRoles.clear();if(modal&&modal!=='audio')closeModal();}
 if(state.phase==='vote'&&state.me){const chosen=selections.get(state.turn.id)||[];selections.set(state.turn.id,chosen.filter(id=>state.turn.options.some(o=>o.id===id&&!o.owned)&&state.me.hint?.eliminated!==id));}
 const oldKey=app.dataset.draftKey,active=document.activeElement?.dataset?.draft;let cursor=null;try{cursor=document.activeElement?.selectionStart;}catch{}
 if(oldKey)document.querySelectorAll('[data-draft]').forEach(el=>drafts.set(`${oldKey}:${el.dataset.draft}`,el.value));persistDrafts();const key=draftKey();
 gameCast?.destroy();gameCast=null;
 document.body.dataset.view=state.host?'host':'phone';app.innerHTML=state.host?hostView():phoneView();app.dataset.draftKey=key;if(changed)app.firstElementChild.classList.add('new-phase');
 document.querySelectorAll('[data-draft]').forEach(el=>{const value=drafts.get(`${key}:${el.dataset.draft}`);if(value!==undefined)el.value=value;el.oninput=()=>{drafts.set(`${key}:${el.dataset.draft}`,el.value);persistDrafts();updateCharacterCount();};if(oldKey===key&&el.dataset.draft===active){el.focus({preventScroll:true});try{if(cursor!==null)el.setSelectionRange(cursor,cursor);}catch{}}});
 gameCast=mountGameCast(app,state);bind();if(busy)document.querySelectorAll('#submission button[type="submit"],#submit-drawing,#lock-vote,#use-power').forEach(b=>{if(!b.disabled){b.disabled=true;b.setAttribute('aria-busy','true');}});updateTimer();updateCharacterCount();audio.setHost(state.host);audio.setPhase(state.phase);audio.paused=state.paused;updateConnection();
 if(state.host&&oldState){if(state.players.length>oldState.players.length)audio.effect('join');if(changed)audio.effect(state.phase==='finished'?'win':state.round!==oldState.round?(state.round===3?'finale':'round'):state.phase==='reveal'?'reveal':'submit');}
 if(changed&&oldState&&state.host&&oldState.code===state.code&&state.phase!=='lobby'&&state.round!==oldState.round)transition(true,state.round===3);
 if(changed&&['reveal','finished'].includes(state.phase)){celebrate();animateScores(oldState,scoreRects);}
 if(!state.host&&state.me.role&&state.round===1&&!seenRoles.has(state.me.role.id+state.code)){
  seenRoles.add(state.me.role.id+state.code);const epoch=navigationEpoch;
  const storage=`alibi-role:${auth?.token}:${state.matchId}`;let viewed=false;try{viewed=sessionStorage.getItem(storage)==='seen';sessionStorage.setItem(storage,'seen');}catch{}
  if(!viewed)setTimeout(()=>{if(epoch===navigationEpoch&&state?.round===1&&!state.host&&!modal){modal='role';renderModal();}},oldState?950:0);
 }
 if(modal)renderModal();lastFrame=frame;lastSignature=signature;lastState=JSON.parse(JSON.stringify(state));
}
function updateCharacterCount(){const input=$('#answer'),count=$('#character-count');if(input&&count)count.textContent=`${input.value.length} / ${input.maxLength}`;}
function bind(){
 document.querySelectorAll('[data-enlarge]').forEach(el=>el.onclick=()=>{galleryIndex=Number(el.dataset.enlarge);modal='gallery';renderModal();});
 if($('#question-starter'))$('#question-starter').onclick=()=>{const input=$('#answer');const target=name(state.me.questionTarget),starters=[`What would ${target} get banned from a petting zoo for?`,`What does ${target} take way too seriously?`,`What would ${target} sell at a very unsuccessful shop?`,`What would ${target} bring to witness protection?`];const current=starters.indexOf(input.value);if(input.value&&current<0&&!confirm('Replace your current draft with a starter?'))return;input.value=starters[(current+1)%starters.length];input.oninput();input.focus();};
document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));document.querySelectorAll('[data-kick]').forEach(el=>el.onclick=()=>action('kick',{playerId:el.dataset.kick}));if($('#end-timer'))$('#end-timer').onclick=()=>{if(confirm('End this timer? Missing submissions will be skipped.'))action('advance');};if($('#copy-link'))$('#copy-link').onclick=async()=>{const link=`${network[0]||location.origin}/join?room=${state.code}`;try{await navigator.clipboard.writeText(link);toast('Invite copied. Unleash it.');}catch{toast(`Join at ${link}`);}};
if($('#submission'))$('#submission').onsubmit=e=>{e.preventDefault();action(e.target.dataset.type,Object.fromEntries(new FormData(e.target)));};
document.querySelectorAll('[data-option]').forEach(el=>el.onclick=()=>{const id=el.dataset.option;let chosen=selections.get(state.turn.id)||[];if(chosen.includes(id))chosen=chosen.filter(v=>v!==id);else chosen=state.me.power?.role==='lucky'?[...chosen.slice(-1),id]:[id];selections.set(state.turn.id,chosen);render();});if($('#lock-vote'))$('#lock-vote').onclick=()=>action('vote',{choices:selections.get(state.turn.id)||[]});
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{if(el.dataset.page==='options')optionPage+=Number(el.dataset.step);else scorePage+=Number(el.dataset.step);render();});document.querySelectorAll('[data-result-tab]').forEach(el=>el.onclick=()=>{resultTab=el.dataset.resultTab;render();});
if($('#drawing'))initCanvas();else initCanvas.observer?.disconnect();if($('#edit-character'))$('#edit-character').onclick=()=>openCharacter();if($('#open-role'))$('#open-role').onclick=()=>{modal='role';renderModal();};if($('#sound-settings'))$('#sound-settings').onclick=()=>{modal='audio';renderModal();};}
function openCharacter(){editingCharacter={...(state?.me?player(state.me.id).character:myCharacter)};avatarPart='head';modal='character';renderModal();}
function closeModal(){const video=$('#feature-video');video?.pause?.();audio.setPreview(false);modal=null;$('#overlays').innerHTML='';playground?.setQuiet(homeJoining);}
function renderModal(){audio.setPreview(modal==='preview');const root=$('#overlays');if(!modal){root.innerHTML='';return;}playground?.setQuiet(true);let content='',title='';
if(modal==='character'){title='Make your character.';content=`<div class="character-editor"><div class="character-preview">${characterSvg(editingCharacter)}<button class="text-button" id="random-character">surprise me ↻</button></div><div class="character-controls"><div class="part-tabs">${Object.keys(PARTS).map(part=>`<button data-part="${part}" class="${part===avatarPart?'active':''}" aria-pressed="${part===avatarPart}">${LABELS[part]}</button>`).join('')}</div><div class="part-options">${PARTS[avatarPart].map(value=>`<button class="part-option ${editingCharacter[avatarPart]===value?'active':''}" data-choice="${value}" aria-pressed="${editingCharacter[avatarPart]===value}">${avatarPart==='color'?`<span class="color-dot" style="background:${COLORS[value]}"></span>`:characterSvg({...editingCharacter,[avatarPart]:value},{faceOnly:!['pose','outfit'].includes(avatarPart)})}<span>${value==='none'?'nothing':value}</span></button>`).join('')}</div><button class="btn red full" id="save-character">Save character</button></div></div>`;}
if(modal==='role'){const me=state.me,r=me.role,info=roleState(state),{available,targeted,targets}=info;title=r.name;
content=`<div class="role-reveal"><div class="role-character">${avatar(player(me.id))}${roleArt(r.id)}</div><p class="secret-stamp">Only on your phone · use once in rounds 1–2</p><p class="role-description">${esc(r.description)}</p><p class="role-when">${esc(info.label)}</p>${r.id==='gambler'&&!me.used?'<p class="wager-note">Right: +1,000. Wrong or no vote: −250.</p>':''}${me.hint?.peek?`<p class="notice">${esc(name(me.hint.target))} picked ${me.hint.peek.map(id=>String.fromCharCode(65+state.turn.options.findIndex(o=>o.id===id))).join(' + ')}.</p>`:''}${available?`${targeted?`<label for="power-target">Choose a player</label><select id="power-target">${targets.map(p=>`<option value="${p.id}" ${roleTarget===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select>`:''}<button class="btn red full" id="use-power">${r.id==='gambler'?'Place my wager':'Use power'}</button>`:''}<button class="text-button" data-close-modal>Got it</button></div>`;}
if(modal==='gallery'){const list=state.turn.options;galleryIndex=Math.max(0,Math.min(galleryIndex,list.length-1));const o=list[galleryIndex];title=`Drawing ${String.fromCharCode(65+galleryIndex)}`;content=`<div class="gallery-zoom">${drawingSvg(o.drawing)}<div class="gallery-controls"><button class="text-button" id="gallery-prev" ${galleryIndex===0?'disabled':''}>Previous</button><span>${galleryIndex+1} / ${list.length}</span><button class="text-button" id="gallery-next" ${galleryIndex===list.length-1?'disabled':''}>Next</button></div>${state.phase==='vote'&&state.me?.canVote&&!state.me.voted?`<button class="btn red full" id="gallery-pick" ${o.owned?'disabled':''}>${o.owned?'Your drawing':'Select this drawing'}</button>`:''}<button class="text-button" data-close-modal>Back to the gallery</button></div>`;}
if(modal==='audio'){title='paper trails.';content=`<div class="audio-settings">${doodle('mug')}<p>A warm little soundtrack for questionable answers.<br>${state?.host?'Only this shared screen makes a sound.':'Music for the menu and shared screen. Player phones stay quiet.'}</p><button class="btn yellow full" id="toggle-audio" ${audio.loading?'disabled':''}>${audio.loading?'loading music…':audio.enabled?'mute the music':'play music ♫'}</button><label for="volume">volume</label><input id="volume" type="range" min="0" max="60" value="${Math.round(audio.volume*100)}"><p id="audio-status" class="smallnote" role="status">${esc(audio.error)}</p><p class="smallnote">Keep it low. Your friends are already loud.</p></div>`;}
if(modal==='rules'){title='how this mess works.';content=`<div class="rules-sheet"><p><b>1. tell the truth. or don't.</b><br>A question about one friend. They answer honestly. Everyone else writes a believable lie.</p><p><b>2. pick the real answer.</b><br>500 for getting it right. 250 for each person your lie fools. Your own answer is off limits.</p><p><b>3. get personal. then draw.</b><br>Round two uses your questions. In the finale, one artist knows the answer. Everyone else draws a guess. Find the informed drawing for 1,000.</p><p><b>also: secret powers.</b><br>Everybody gets one. Check yours on your phone.</p><button class="btn red full" data-close-modal>sounds like a terrible idea. i'm in.</button></div>`;}
if(modal==='preview'){title='a little tour of the chaos.';content=`<div class="feature-preview"><video id="feature-video" controls playsinline preload="none" poster="/media/preview-poster.webp" aria-label="Alibi: four characters explain joining, bluffing, secret roles, drawing, scoring, and reconnecting"><source src="/media/alibi-preview.mp4" type="video/mp4"><track kind="captions" src="/media/alibi-preview.vtt" srclang="en" label="English">Your browser cannot play this video. <a href="/media/alibi-preview.mp4">Download the walkthrough</a>.</video><p class="preview-note">An 80-second animated walkthrough of one game night, from joining to the final drawing. Original music and speech bubbles; easy to follow on mute.</p><details class="preview-transcript"><summary>Read the walkthrough</summary><p><b>Your friend:</b> Alibi is a party game about your friends.</p><p><b>Your friend:</b> Join on your phone. Everyone shares one screen.</p><p><b>Cowboy:</b> Pick your character. Make yourself at home.</p><p><b>Flower:</b> One friend answers a question. Everyone else writes a lie.</p><p><b>Frog:</b> Now vote: which answer is actually true?</p><p><b>Cowboy:</b> Find the truth for points. Fool friends for more.</p><p><b>Cape:</b> Round two: write questions about each other.</p><p><b>Flower:</b> Secret roles give you a little help.</p><p><b>Cowboy:</b> Final round: I answer a question, then sit out.</p><p><b>Cape:</b> I see Cowboy’s answer. The other artists only see the question.</p><p><b>Flower:</b> Time to draw. You get 90 seconds.</p><p><b>Frog:</b> Which drawing came from the artist who knew?</p><p><b>Cape:</b> Timers, scores, and reconnecting? All handled.</p><p><b>Flower:</b> Most points wins. Think you know your friends?</p></details><div class="preview-actions"><button class="text-button" id="preview-about">how it was built ↗</button><button class="btn yellow" data-close-modal>back to the game ↗</button></div></div>`;}
if(modal==='about'){title='behind the notebook.';content=`<div class="project-story"><p class="project-byline">Alibi · built by Ben Llados with GPT</p><p>A browser party game designed to turn things friends know about each other into believable lies, bad drawings, and arguments over points.</p><dl><div><dt>The product challenge</dt><dd>Make a multiplayer game easy to join, clear on a shared screen, and personal enough to keep a group laughing.</dd></div><div><dt>The work</dt><dd>Game rules, visual direction, playtesting, and iteration with GPT-assisted implementation. Feedback shaped the finale, answer matching, timers, characters, and this first-time experience.</dd></div><div><dt>Under the notebook</dt><dd>Node.js owns the game state, timers, and scoring. Live server-sent events keep devices updated. Each player receives a private view for answers and roles. Canvas handles drawing; SVG builds the characters and smiley transition.</dd></div><div><dt>The current tradeoff</dt><dd>Rooms live in one server's memory. Players can reconnect, but a server restart clears games. Durable rooms are a next step.</dd></div></dl><div class="project-links"><button class="btn yellow" id="about-preview">Watch the walkthrough ▶</button><a href="https://github.com/benllados/alibi" target="_blank" rel="noopener noreferrer">View the code ↗</a></div></div>`;}
root.innerHTML=`<div class="modal-backdrop"><section class="modal-sheet modal-${modal}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><i class="tape"></i><button class="modal-close" data-close-modal aria-label="Close">×</button><h2 id="modal-title">${esc(title)}</h2>${content}</section></div>`;
root.querySelectorAll('[data-close-modal]').forEach(el=>el.onclick=closeModal);root.querySelector('.modal-backdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal();};root.querySelectorAll('[data-part]').forEach(el=>el.onclick=()=>{avatarPart=el.dataset.part;renderModal();});root.querySelectorAll('[data-choice]').forEach(el=>el.onclick=()=>{editingCharacter[avatarPart]=el.dataset.choice;renderModal();});if($('#random-character'))$('#random-character').onclick=()=>{editingCharacter=randomCharacter();renderModal();};if($('#save-character'))$('#save-character').onclick=async()=>{const character={...editingCharacter};if(state?.me){if(!await action('character',{character}))return;}myCharacter=character;try{localStorage.setItem('alibi-character',JSON.stringify(character));}catch{}closeModal();if(!state){const label=$('#pick-character .avatar');if(label)label.innerHTML=characterSvg(myCharacter);}};
if($('#power-target'))$('#power-target').onchange=e=>roleTarget=e.target.value;if($('#use-power'))$('#use-power').onclick=async()=>{const target=$('#power-target')?.value;closeModal();await action('power',{target});};if($('#toggle-audio'))$('#toggle-audio').onclick=async()=>{if(audio.enabled)audio.stop();else if(!await audio.enable())toast(audio.error||'Audio could not start. Try again.');if(state)render();else renderModal();};if($('#volume'))$('#volume').oninput=e=>audio.setVolume(Number(e.target.value)/100);
if($('#about-preview'))$('#about-preview').onclick=()=>{modal='preview';renderModal();};
if($('#preview-about'))$('#preview-about').onclick=()=>{$('#feature-video')?.pause?.();modal='about';renderModal();};
if($('#gallery-prev'))$('#gallery-prev').onclick=()=>{galleryIndex--;renderModal();};if($('#gallery-next'))$('#gallery-next').onclick=()=>{galleryIndex++;renderModal();};if($('#gallery-pick'))$('#gallery-pick').onclick=()=>{selections.set(state.turn.id,[state.turn.options[galleryIndex].id]);optionPage=Math.floor(galleryIndex/pageSize());closeModal();render();};
const first=root.querySelector('button');first?.focus({preventScroll:true});}
function transition(roundChange,finale){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const ms=Math.max(0,Math.min(1800,(state.phaseStartsAt||0)-(Date.now()+offset)));if(ms<250)return;const curtain=$('#transition');clearTimeout(transition.timer);curtain.className=`transition running round-change ${finale?'finale':''}`;curtain.innerHTML=`<div class="transition-logo">${wordmark()}</div><div class="round-intro-copy"><small>Round ${state.round}</small><h2>${esc(names[state.round])}</h2><p>${esc(phaseGuide(state))}</p></div>${finale?`<div class="flames">${Array.from({length:9},(_,i)=>doodle('flame',`flame f${i}`)).join('')}</div>`:''}`;transition.timer=setTimeout(()=>{curtain.className='transition';curtain.innerHTML='';},ms);}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const root=$('#celebration');root.innerHTML=Array.from({length:state.phase==='finished'?40:18},(_,i)=>`<i style="--x:${(i*67)%100}%;--r:${i*83}deg;--delay:${i%7*.06}s;--color:${Object.values(COLORS)[i%8]}"></i>`).join('');clearTimeout(celebrate.timer);celebrate.timer=setTimeout(()=>root.innerHTML='',2600);}
function animateScores(old,rects){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const sorted=[...state.players].sort((a,b)=>b.score-a.score),previousOrder=[...(old?.players||state.players)].sort((a,b)=>b.score-a.score);
 const previousLead=Math.max(...previousOrder.map(p=>p.score)),lead=sorted[0]?.score;
 document.querySelectorAll('[data-score-player]').forEach(el=>{
  const id=el.dataset.scorePlayer,p=player(id),previous=rects.get(id),now=el.getBoundingClientRect(),from=old?.players.find(v=>v.id===id)?.score??p.score,to=p.score;
  const shift=previous?previous.top-now.top:(previousOrder.findIndex(v=>v.id===id)-sorted.findIndex(v=>v.id===id))*now.height;
  if(shift)el.animate([{transform:`translateY(${shift}px)`},{transform:'translateY(0)'}],{duration:850,easing:'cubic-bezier(.2,.8,.2,1)'});
  if(p.score===lead&&old?.players.find(v=>v.id===id)?.score<previousLead)el.classList.add('new-leader');
  const score=el.querySelector('[data-score]'),start=performance.now();
  function count(t){if(!score.isConnected)return;const progress=Math.min(1,(t-start)/900);score.textContent=Math.round(from+(to-from)*(1-(1-progress)**3)).toLocaleString();if(progress<1)requestAnimationFrame(count);}requestAnimationFrame(count);
  if(!state.host||state.phase!=='reveal'||from===to)return;
  const option=state.turn.options.find(o=>!o.truth&&o.owners.includes(id)&&o.voters.length)||state.turn.options.find(o=>o.truth);
  const source=option&&document.querySelector(`[data-answer="${option.id}"]`);if(!source)return;const origin=source.getBoundingClientRect();
  const points=document.createElement('span');points.className='point-flight';points.textContent=`${to>from?'+':''}${to-from}`;points.style.left=`${origin.left+origin.width/2}px`;points.style.top=`${origin.top+origin.height/2}px`;document.body.append(points);
  const flight=points.animate([{transform:'translate(-50%,-50%) scale(.6)',opacity:0},{transform:'translate(-50%,-50%) scale(1.25)',opacity:1,offset:.22},{transform:`translate(${now.right-origin.left-origin.width/2-40}px,${now.top-origin.top-origin.height/2}px) scale(.8)`,opacity:0}],{duration:1000,delay:180,easing:'ease-in-out',fill:'both'});
  flight.finished.then(()=>points.remove(),()=>points.remove());
 });
}
function initCanvas(){
 const canvas=$('#drawing'),ctx=canvas.getContext('2d'),key=state.turn.id;
 if(!drawings.has(key))drawings.set(key,[]);if(!redoStrokes.has(key))redoStrokes.set(key,[]);
 const strokes=drawings.get(key),redo=redoStrokes.get(key);let current=null,paintRequest=0,cleared=null;
 initCanvas.observer?.disconnect();
 const fit=()=>{const r=canvas.parentElement.getBoundingClientRect(),width=Math.min(r.width-4,(r.height-4)*4/3);if(width>0){canvas.style.width=`${width}px`;canvas.style.height=`${width*3/4}px`;}};fit();
 if(typeof ResizeObserver!=='undefined'){initCanvas.observer=new ResizeObserver(fit);initCanvas.observer.observe(canvas.parentElement);}
 const tools=()=>{$('#undo').disabled=!strokes.length&&!cleared;$('#redo').disabled=!redo.length;$('#clear').disabled=!strokes.length;};
 const paint=()=>{paintRequest=0;ctx.fillStyle='white';ctx.fillRect(0,0,600,450);for(const s of strokes){ctx.strokeStyle=s.color;ctx.fillStyle=s.color;ctx.lineWidth=s.size;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();s.points.forEach((p,i)=>{if(!i)ctx.moveTo(p[0]*600,p[1]*450);else ctx.lineTo(p[0]*600,p[1]*450);});if(s.points.length===1){ctx.arc(s.points[0][0]*600,s.points[0][1]*450,s.size/2,0,Math.PI*2);ctx.fill();}else ctx.stroke();}};
 const point=e=>{const r=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))];};
 canvas.onpointerdown=e=>{if(state.paused||busy||e.button>0||current)return;e.preventDefault();if(strokes.length>=180)return toast('Lots of detail! Undo a stroke to keep drawing.');canvas.setPointerCapture(e.pointerId);current={color:ink,size:ink==='#ffffff'?Math.min(25,brush*2):brush,points:[point(e)]};strokes.push(current);redo.splice(0);paint();tools();};
 canvas.onpointermove=e=>{if(!current)return;if(state.paused){current=null;persistDrafts();return;}const p=point(e),last=current.points.at(-1);if(Math.abs(p[0]-last[0])+Math.abs(p[1]-last[1])<.003)return;if(strokes.reduce((sum,s)=>sum+s.points.length,0)>=11990){current=null;persistDrafts();toast('That’s a lot of detail. Submit it or undo a stroke.');return;}current.points.push(p);if(!paintRequest)paintRequest=requestAnimationFrame(paint);};
 canvas.onpointerup=canvas.onpointercancel=()=>{current=null;persistDrafts();tools();};
 $('#brush').value=String(brush);$('#brush').onchange=e=>brush=Number(e.target.value);
 document.querySelectorAll('[data-ink]').forEach(el=>el.onclick=()=>{ink=el.dataset.ink;document.querySelectorAll('[data-ink]').forEach(b=>{b.classList.toggle('active',b.dataset.ink===ink);b.setAttribute('aria-pressed',String(b.dataset.ink===ink));});});
 $('#undo').onclick=()=>{if(busy||state.paused)return;if(strokes.length)redo.push(strokes.pop());else if(cleared){strokes.push(...cleared);cleared=null;redo.splice(0);}current=null;paint();persistDrafts();tools();};
 $('#redo').onclick=()=>{if(busy||state.paused)return;if(redo.length)strokes.push(redo.pop());paint();persistDrafts();tools();};
 $('#clear').onclick=()=>{if(busy||state.paused)return;if(strokes.length&&confirm('Clear this drawing? You can undo this clear.')){cleared=strokes.slice();redo.splice(0);strokes.splice(0);current=null;paint();persistDrafts();tools();}};
 $('#submit-drawing').onclick=()=>{current=null;persistDrafts();if(!strokes.length)return toast('Draw something before submitting.');action('drawing',{strokes});};paint();tools();
}
function updateTimer(){if(!state)return;const ms=state.paused?state.remaining:state.deadline?state.deadline-Date.now()-offset:0;const seconds=Math.min(state.phaseDuration||Infinity,Math.max(0,Math.ceil((ms||0)/1000))),value=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;document.querySelectorAll('.timer').forEach(el=>{el.textContent=value;el.setAttribute('aria-label',`${state.paused?'Paused, ':''}${seconds} seconds remaining`);});document.querySelectorAll('.countdown').forEach(el=>{el.classList.toggle('urgent',state.phase!=='reveal'&&!state.paused&&seconds<=10);el.classList.toggle('is-paused',state.paused);const note=el.querySelector('.clock-note');if(note)note.textContent=clockLabel();el.querySelector('.countdown-fill').style.width=`${Math.max(0,Math.min(100,ms/(state.phaseDuration*1000)*100))}%`;});document.querySelectorAll('[data-next-status]').forEach(el=>el.textContent=revealStatus(seconds));const tick=`${frameKey()}:${seconds}`;if(state.phase!=='reveal'&&state.host&&state.deadline&&!state.paused&&seconds>0&&seconds<=10&&clockTick!==tick){clockTick=tick;audio.effect('tick');}}
function viewport(){const v=window.visualViewport;document.documentElement.style.setProperty('--screen-height',`${v?.height||innerHeight}px`);document.body.classList.toggle('keyboard-open',!!v&&v.height<innerHeight*.77);}viewport();window.visualViewport?.addEventListener('resize',viewport);window.addEventListener('resize',()=>{viewport();if(state&&['vote','reveal','finished'].includes(state.phase))render();});window.addEventListener('pagehide',persistDrafts);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&modal){const focus=[...$('#overlays').querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')];if(!focus.length)return;const index=focus.indexOf(document.activeElement);if(e.shiftKey&&index<=0){e.preventDefault();focus.at(-1).focus();}else if(!e.shiftKey&&index===focus.length-1){e.preventDefault();focus[0].focus();}}});
setInterval(updateTimer,200);fetch('/api/network').then(r=>r.json()).then(result=>{network=result.addresses;if(state?.host&&state.phase==='lobby')render();}).catch(()=>{});
